import { openPlayerFundsDialog } from '../app/player-funds.js';

class AppVrfDonation extends HTMLElement {
  connectedCallback() {
    if (this.querySelector('button')) return;
    this.innerHTML = '<button type="button" class="secondary-action link-trade-open" aria-haspopup="dialog"><span class="link-trade-open__label">FUND GAME RANDOMNESS</span><strong>25% RNG CREDIT</strong></button>';
    this.querySelector('button').addEventListener('click', () => openPlayerFundsDialog('vrf'));
  }
}
if (typeof customElements !== 'undefined' && !customElements.get('app-vrf-donation')) customElements.define('app-vrf-donation', AppVrfDonation);
